<script setup lang="ts">
import { tr } from '../../i18n/index.ts'

import { errorMessage } from '@/utils'
import { computed,onBeforeUnmount,ref,watch } from 'vue'
import { ChevronRight,Copy,FileText,Folder,FolderOpen,GitBranch,RefreshCw,Terminal } from 'lucide-vue-next'
import { useToast } from '@/composables/useToast'
import {useProjectLaunch} from '@/composables/useProjectLaunch'
const launcher=useProjectLaunch()
import type { ProjectDirectoryPage,ProjectOverview,ProjectScript,ProjectTextPage } from '@/types/project'
const props=defineProps<{id:string;path:string}>(),emit=defineEmits<{ask:[text:string]}>(),api=window.baoyi.project,{success,error:toastError}=useToast()
const overview=ref<ProjectOverview|null>(null),overviewError=ref(''),overviewBusy=ref(false)
const repository=ref('')
const directory=ref(''),query=ref(''),listing=ref<ProjectDirectoryPage|null>(null),filesBusy=ref(false),filesError=ref('')
const selected=ref(''),pages=ref<ProjectTextPage[]>([]),pageIndex=ref(0),textBusy=ref(false),textError=ref('')
const scripts=ref<ProjectScript[]>([]),scriptWarnings=ref<string[]>([]),scriptBusy=ref(false),scriptQuery=ref(''),launchBusy=ref(false)
const currentPage=computed(()=>pages.value[pageIndex.value]),filteredScripts=computed(()=>scripts.value.filter(s=>(s.name+' '+s.command).toLocaleLowerCase().includes(scriptQuery.value.trim().toLocaleLowerCase())))
const crumbs=computed(()=>directory.value.split(/[\\/]/).filter(Boolean).map((name,i,parts)=>({name,path:parts.slice(0,i+1).join('/')})))
let overviewRun=0,filesRun=0,textRun=0,scriptsRun=0,queryTimer:ReturnType<typeof setTimeout>|undefined
async function loadOverview(refresh=false,repoPath?:string){const run=++overviewRun;overviewBusy.value=true;overviewError.value='';try{const value=await api.overview(props.id,{refresh,repoPath});if(run===overviewRun){overview.value=value;repository.value=value.git.repoPath}}catch(e){if(run===overviewRun)overviewError.value=errorMessage(e)}finally{if(run===overviewRun)overviewBusy.value=false}}
async function loadFiles(more=false){const run=++filesRun,old=listing.value;filesBusy.value=true;filesError.value='';try{
  const result=await api.files(props.id,directory.value,{query:query.value,cursor:more&&old?.next?{...old.next}:undefined})
  if(run===filesRun)listing.value={...result,files:more&&old?[...old.files,...result.files]:result.files}
}catch(e){if(run===filesRun)filesError.value=errorMessage(e)}finally{if(run===filesRun)filesBusy.value=false}}
async function loadScripts(){const run=++scriptsRun;scriptBusy.value=true;try{const result=await api.scripts(props.id,directory.value);if(run===scriptsRun){scripts.value=result.scripts;scriptWarnings.value=result.warnings}}catch(e){if(run===scriptsRun){scripts.value=[];scriptWarnings.value=[errorMessage(e)]}}finally{if(run===scriptsRun)scriptBusy.value=false}}
function navigate(relative:string){clearTimeout(queryTimer);directory.value=relative;query.value='';listing.value=null;selected.value='';pages.value=[];textError.value='';textRun++;textBusy.value=false;scripts.value=[];void loadFiles();void loadScripts()}
function search(){clearTimeout(queryTimer);queryTimer=setTimeout(()=>void loadFiles(),180)}
async function preview(relative:string,more=false){const run=++textRun;selected.value=relative;textBusy.value=true;textError.value='';const previous=currentPage.value
  if(!more){pages.value=[];pageIndex.value=0}
  try{const result=await api.readFile(props.id,relative,more&&previous?.next?{...previous.next}:undefined);if(run===textRun){pages.value.push(result);pageIndex.value=pages.value.length-1}}
  catch(e){if(run===textRun)textError.value=errorMessage(e)}finally{if(run===textRun)textBusy.value=false}
}
function nextPage(){if(pageIndex.value<pages.value.length-1)pageIndex.value++;else void preview(selected.value,true)}
async function open(relative:string){if(launchBusy.value)return;launchBusy.value=true;try{await api.openFile(props.id,relative)}catch(e){toastError(errorMessage(e))}finally{launchBusy.value=false}}
async function terminal(){if(launchBusy.value)return;launchBusy.value=true;try{await api.openTerminal(props.id,directory.value);success(tr("已在当前目录打开 PowerShell"))}catch(e){toastError(errorMessage(e))}finally{launchBusy.value=false}}
async function copy(text:string){try{await window.baoyi.app.copyText(text);success(tr("已复制"))}catch{toastError(tr("复制失败，请手动选择文字复制"))}}
watch(()=>[props.id,props.path],()=>{overview.value=null;void loadOverview();navigate('')},{immediate:true})
onBeforeUnmount(()=>{overviewRun++;filesRun++;textRun++;scriptsRun++;clearTimeout(queryTimer)})
</script>

<template><div class="project-workspace">
  <header class="work-heading"><div><h2>{{ $t("回到工作现场") }}</h2><p>{{ $t("查看文件、准备命令，接着上次的工作。") }}</p></div><button class="pj-button" :disabled="overviewBusy" @click="loadOverview(true)"><RefreshCw :size="15"/>{{ $t("刷新状态") }}</button><button class="pj-button pj-primary" @click="emit('ask',$t('阅读项目说明，解释这个项目的用途和主要入口，再给出有依据的项目资料建议。'))">{{ $t("让助手了解项目") }}</button></header>
  <section class="work-git"><GitBranch :size="17"/><div><strong>{{overviewBusy?$t('正在读取 Git 状态…'):overview?.git.available?overview.git.branch:$t('工作区状态')}}</strong><p v-if="overviewError" class="pj-error" role="alert">{{overviewError}}</p><p v-else>{{overview?.git.available?(overview.git.changed?overview.git.changed+$t(' 个文件有变化'):$t('工作区干净')):overview?.git.message||$t('文件与命令可独立浏览')}}</p><small v-if="overview?.git.readAt">{{ $t("{p0} · {p1} 读取 · 缓存 30 秒", {p0: (overview.git.repoPath||$t('项目根目录')), p1: (new Date(overview.git.readAt).toLocaleTimeString($locale))}) }}</small></div><details v-if="overview?.git.status"><summary>{{ $t("查看变化") }}</summary><pre>{{overview.git.status}}</pre><p v-if="overview.git.truncated">{{ $t("状态较长，仅显示前 12,000 字。") }}</p></details></section>
  <form class="repository-choice" @submit.prevent="loadOverview(true,repository)"><label>{{ $t("Git 仓库") }}<input v-model="repository" list="project-repository-paths" :placeholder="$t('项目内相对目录，留空自动选择')" :aria-label="$t('Git 仓库相对目录')"/></label><datalist id="project-repository-paths"><option v-for="candidate in overview?.git.candidates||[]" :key="candidate" :value="candidate"/></datalist><button class="pj-button" :disabled="overviewBusy">{{ $t("读取此仓库") }}</button></form>
  <div class="work-location"><nav :aria-label="$t('项目目录')"><button @click="navigate('')">{{ $t("项目根位置") }}</button><template v-for="crumb in crumbs" :key="crumb.path"><ChevronRight :size="13"/><button @click="navigate(crumb.path)">{{crumb.name}}</button></template></nav><button class="pj-icon" :aria-label="$t('复制项目路径')" @click="copy(path)"><Copy :size="15"/></button></div>
  <div class="work-browser">
    <section class="work-files"><header><input v-model="query" :aria-label="$t('搜索当前目录')" :placeholder="$t('搜索当前目录…')" @input="search"/><button class="pj-icon" :aria-label="$t('刷新当前目录')" :disabled="filesBusy" @click="loadFiles()"><RefreshCw :size="15"/></button></header>
      <p class="work-caption">{{ $t("{p0} · 点击目录进入，点击文件预览", {p0: (listing?listing.files.length+' / '+listing.total+$t(' 项'):$t('目录内容'))}) }}</p>
      <p v-if="filesError" class="pj-error" role="alert">{{filesError}} <button class="pj-button" :disabled="filesBusy" @click="loadFiles()">{{ $t("重新读取目录") }}</button></p>
      <p v-if="filesBusy&&!listing" role="status">{{ $t("正在读取目录…") }}</p><p v-else-if="listing&&!listing.files.length" class="pj-muted">{{query?$t('当前目录没有匹配项'):$t('此目录没有可浏览的文件')}}</p>
      <ul><li v-for="file in listing?.files||[]" :key="file.path"><button :class="{selected:selected===file.path}" :aria-label="(file.directory?$t('进入目录 '):$t('预览文件 '))+file.path" @click="file.directory?navigate(file.path):preview(file.path)"><Folder v-if="file.directory" :size="16"/><FileText v-else :size="16"/><span>{{file.path.split(/[\\/]/).pop()}}</span><ChevronRight v-if="file.directory" :size="13"/></button></li></ul>
      <button v-if="listing?.next" class="pj-button" :disabled="filesBusy" @click="loadFiles(true)">{{filesBusy?$t('正在读取…'):$t('加载更多文件')}}</button><p class="work-caption">{{ $t("凭据、依赖及构建目录不在这里展示。") }}</p>
    </section>
    <section class="work-preview"><header><strong>{{selected||$t('文件预览')}}</strong><button v-if="selected" class="pj-button" :disabled="launchBusy" @click="open(selected)"><FolderOpen :size="14"/>{{ $t("用系统应用打开") }}</button></header>
      <p v-if="!selected" class="work-placeholder">{{ $t("从左侧选一份说明、文稿或代码。") }}<br/>{{ $t("这里只读预览，修改可在原来的工具中继续。") }}</p>
      <p v-if="textError" class="pj-error" role="alert">{{textError}} <button class="pj-button" :disabled="textBusy" @click="preview(selected)">{{ $t("重新读取文件") }}</button></p>
      <p v-if="textBusy" role="status">{{ $t("正在读取文件…") }}</p><template v-if="currentPage"><div class="work-paging"><span>{{ $t("第 {p0} 页 · 从第 {p1} 行开始 · {p2} 字节", {p0: (pageIndex+1), p1: (currentPage.startLine), p2: (currentPage.size.toLocaleString($locale))}) }}</span><button class="pj-button" :disabled="textBusy||pageIndex===0" @click="pageIndex--">{{ $t("上一页") }}</button><button class="pj-button" :disabled="textBusy||(!currentPage.next&&pageIndex===pages.length-1)" @click="nextPage">{{ $t("下一页") }}</button></div><pre class="work-text">{{currentPage.text||$t('（空文件）')}}</pre></template>
    </section>
  </div>
  <section class="work-commands"><header><div><h3><Terminal :size="17"/>{{ $t("当前目录的启动命令") }}</h3><p>{{ $t("复制命令后，在这个目录的终端里运行。") }}</p></div><button class="pj-button" :disabled="scriptBusy" @click="loadScripts">{{ $t("重新发现命令") }}</button><button class="pj-button" :disabled="launchBusy" @click="terminal"><Terminal :size="15"/>{{ $t("在当前目录打开终端") }}</button></header>
    <input v-if="scripts.length" v-model="scriptQuery" :aria-label="$t('搜索项目命令')" :placeholder="$t('搜索命令…')"/><p v-for="warning in scriptWarnings" :key="warning" class="pj-error" role="status">{{$systemMessage(warning)}}</p><p v-if="scriptBusy" role="status">{{ $t("正在读取命令…") }}</p><p v-else-if="!scripts.length" class="pj-muted">{{ $t("此目录没有发现 package.json 脚本或 Makefile 目标。可以进入子目录继续查找，或添加常用工具入口。") }}</p><p v-else-if="!filteredScripts.length" class="pj-muted">{{ $t("没有匹配的命令。") }}</p>
    <article v-for="command in filteredScripts" :key="command.source+':'+command.name"><div><strong>{{command.name}}</strong><small>{{ $t("{p0} · 工作目录 {p1}", {p0: (command.source), p1: (command.cwd)}) }}</small><code>{{command.command}}</code><p v-if="!command.runCommand" class="pj-muted">{{ $t("需要手动确认包管理器或命令名称。") }}</p></div><button class="pj-button pj-primary" :disabled="!command.runCommand||launcher.busy.value" :aria-label="$t('运行脚本 ')+command.name+' '+command.source" @click="launcher.runScript(id,command)">{{ $t("直接运行") }}</button><button class="pj-button" :disabled="!command.runCommand" :aria-label="$t('复制命令 ')+command.name+' '+command.source" @click="copy(command.runCommand!)"><Copy :size="14"/>{{command.runCommand||$t('无法生成命令')}}</button><button class="pj-button" :disabled="!command.runCommand" @click="launcher.openById(id,command)">{{ $t("加入启动菜单") }}</button></article>
  </section>
</div></template>

<style scoped>
.repository-choice{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin:12px 0 22px}.repository-choice label{display:flex;gap:10px;align-items:center;font-size:12px;color:var(--text-sub)}.repository-choice input{min-width:260px;max-width:100%;padding:8px;border:1px solid var(--divider);border-radius:6px;background:var(--bg-card);color:var(--text-main)}.work-git small{font-size:11px;color:var(--text-faint)}

.project-workspace{padding:24px}.work-heading,.work-commands>header{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.work-heading>div,.work-commands>header>div{flex:1;min-width:200px}.work-heading h2{font-size:20px;margin:0 0 7px}.work-heading p,.work-commands p{font-size:12px;color:var(--text-sub);line-height:1.7;margin:6px 0}.work-git{display:flex;gap:12px;align-items:flex-start;background:var(--active-surface);border-radius:8px;padding:16px;margin:20px 0}.work-git>svg{color:var(--accent);flex:none}.work-git>div{flex:1;min-width:0}.work-git strong{font-size:13px;overflow-wrap:anywhere}.work-git p{font-size:12px;color:var(--text-sub);margin:6px 0 0}.work-git details{max-width:65%;font-size:12px}.work-git pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:200px;overflow:auto}.work-location,.work-location nav{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.work-location{margin-bottom:12px;font-size:12px}.work-location nav{flex:1}.work-location button{color:var(--accent);overflow-wrap:anywhere}.work-browser{display:grid;grid-template-columns:minmax(190px,.7fr) minmax(0,1.5fr);border:1px solid var(--divider);border-radius:9px;overflow:hidden}.work-files{padding:14px;border-right:1px solid var(--divider);min-width:0}.work-files>header,.work-preview>header{display:flex;gap:8px;align-items:center}.work-files input,.work-commands>input{border:1px solid var(--divider);padding:8px 10px;background:var(--bg-main);border-radius:6px;min-width:0;color:var(--text-main);font-size:12px}.work-files input{width:100%}.work-caption{font-size:11px;color:var(--text-faint);line-height:1.7}.work-files ul{padding:0;margin:8px 0;list-style:none;max-height:380px;overflow:auto}.work-files li button{display:flex;align-items:center;gap:8px;width:100%;padding:9px 7px;text-align:left;border-radius:5px;font-size:12px;color:var(--text-sub)}.work-files li button:hover,.work-files li button.selected{background:var(--active-surface);color:var(--accent)}.work-files li span{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.work-files li svg{flex:none}.work-preview{min-width:0;background:var(--bg-main);padding:16px}.work-preview>header{flex-wrap:wrap;justify-content:space-between}.work-preview>header strong{font-size:12px;overflow-wrap:anywhere}.work-placeholder{color:var(--text-faint);line-height:2;font-size:13px;padding:45px 8px}.work-paging{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:15px 0;font-size:10px;color:var(--text-faint)}.work-paging>span{flex:1}.work-paging button{font-size:11px;padding:5px 8px}.work-text{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.8 Consolas,monospace;max-height:430px;overflow:auto;tab-size:2;color:var(--text-main)}.work-commands{margin-top:24px}.work-commands h3{display:flex;gap:8px;align-items:center;font-size:15px;margin:0}.work-commands>input{margin:15px 0 4px;width:min(100%,360px)}.work-commands article{display:flex;gap:12px;align-items:center;padding:14px 0;border-bottom:1px solid var(--divider);min-width:0}.work-commands article>div{min-width:0;flex:1}.work-commands article strong{font-size:13px;overflow-wrap:anywhere}.work-commands small{display:block;font-size:10px;color:var(--text-faint);margin:5px 0;overflow-wrap:anywhere}.work-commands code{display:block;font:12px/1.7 Consolas,monospace;color:var(--text-sub);overflow-wrap:anywhere}.work-commands article button{max-width:45%;white-space:normal;overflow-wrap:anywhere;font-size:11px}.work-commands .pj-error{color:var(--danger)}@media(max-width:1000px){.project-workspace{padding:16px}.work-browser{grid-template-columns:minmax(0,1fr)}.work-files{border-right:0;border-bottom:1px solid var(--divider)}.work-files ul{max-height:220px}.work-git{flex-wrap:wrap}.work-git details{max-width:100%}}
</style>
